// Äußere Response aus dem HTTP-Node
const wrapper = $json;

// globale Workflow-Daten holen
const staticData = $getWorkflowStaticData('global');

if (typeof staticData.deletedCount !== 'number') {
  staticData.deletedCount = 0;
}
if (!Array.isArray(staticData.debugEmailsAll)) {
  staticData.debugEmailsAll = [];
}
if (!Array.isArray(staticData.debugEmailsUnique)) {
  staticData.debugEmailsUnique = [];
}
if (!Array.isArray(staticData.debugNextUrls)) {
  staticData.debugNextUrls = [];
}
if (!Array.isArray(staticData.debugDuplicateEmails)) {
  staticData.debugDuplicateEmails = [];
}

// Eigentliche API-Response bestimmen
let response = wrapper;

// Falls die Response in wrapper.data als JSON-String steckt -> parsen
if (typeof wrapper.data === 'string') {
  try {
    response = JSON.parse(wrapper.data);
  } catch (error) {
    staticData.nextUrl = null;

    return [
      {
        json: {
          found: false,
          parseError: true,
          message: 'Response konnte nicht geparst werden',
          rawData: wrapper.data,
          deletedCount: staticData.deletedCount,
        },
      },
    ];
  }
}

// Falls wrapper.data schon ein Objekt ist, dieses verwenden
else if (wrapper.data && typeof wrapper.data === 'object') {
  response = wrapper.data;
}

// Jetzt normal auf Klaviyo-Struktur zugreifen
const profiles = Array.isArray(response.data) ? response.data : [];
const nextUrl = response.links?.next || null;

// nextUrl global speichern
staticData.nextUrl = nextUrl;

// verwendete nextUrl debuggen
if (nextUrl) {
  staticData.debugNextUrls.push(nextUrl);
}

// Keine Profile mehr gefunden
if (profiles.length === 0) {
  return [
    {
      json: {
        found: false,
        message: 'Keine Profile mehr gefunden',
        deletedCount: staticData.deletedCount,
      },
    },
  ];
}

// Counter erhöhen
staticData.deletedCount += profiles.length;

// Debug: E-Mails sammeln und Dopplungen prüfen
const uniqueEmails = new Set(staticData.debugEmailsUnique);
const duplicateEmails = new Set(staticData.debugDuplicateEmails);

for (const profile of profiles) {
  const attrs = profile.attributes || {};
  const email = attrs.email || null;

  if (!email) continue;

  // alle E-Mails speichern
  staticData.debugEmailsAll.push(email);

  // Duplikate prüfen
  if (uniqueEmails.has(email)) {
    duplicateEmails.add(email);
  } else {
    uniqueEmails.add(email);
  }
}

// Arrays zurückschreiben
staticData.debugEmailsUnique = Array.from(uniqueEmails);
staticData.debugDuplicateEmails = Array.from(duplicateEmails);

// Profile als einzelne Items zurückgeben
return profiles.map(profile => {
  const attrs = profile.attributes || {};

  return {
    json: {
      found: true,
      profileId: profile.id,
      email: attrs.email,
      deletedCount: staticData.deletedCount,
      isNewPage: true,
    },
  };
});

