const profileId = $json.profileId?.trim();
const email = $json.email?.trim();

if (!email && !profileId) {
  throw new Error('Kein Identifier vorhanden: email oder profileId fehlt.');
}

return {
  ...$json,
  data: {
    type: 'data-privacy-deletion-job',
    attributes: {
      profile: {
        data: {
          type: 'profile',
          attributes: email ? { email } : { id: profileId },
        },
      },
    },
  },
};

